import sys, zlib, struct

def load(path_or_bytes):
    data = path_or_bytes if isinstance(path_or_bytes, bytes) else open(path_or_bytes,'rb').read()
    assert data[:8] == b'\x89PNG\r\n\x1a\n', 'not a png'
    pos, idat, ihdr = 8, [], None
    while pos < len(data):
        ln = struct.unpack('>I', data[pos:pos+4])[0]; typ = data[pos+4:pos+8]
        body = data[pos+8:pos+8+ln]; pos += 12 + ln
        if typ == b'IHDR': ihdr = struct.unpack('>IIBBBBB', body)
        elif typ == b'IDAT': idat.append(body)
        elif typ == b'IEND': break
    w, h, depth, color, comp, filt, inter = ihdr
    assert depth == 8 and inter == 0, f'unsupported depth={depth} interlace={inter}'
    ch = {0:1, 2:3, 3:1, 4:2, 6:4}[color]
    raw = zlib.decompress(b''.join(idat))
    stride = w * ch
    out = bytearray(h * stride); prev = bytearray(stride); p = 0
    for y in range(h):
        f = raw[p]; p += 1
        line = bytearray(raw[p:p+stride]); p += stride
        if f == 1:
            for i in range(ch, stride): line[i] = (line[i] + line[i-ch]) & 255
        elif f == 2:
            for i in range(stride): line[i] = (line[i] + prev[i]) & 255
        elif f == 3:
            for i in range(stride):
                a = line[i-ch] if i >= ch else 0
                line[i] = (line[i] + ((a + prev[i]) >> 1)) & 255
        elif f == 4:
            for i in range(stride):
                a = line[i-ch] if i >= ch else 0
                b = prev[i]; c = prev[i-ch] if i >= ch else 0
                pa, pb, pc = abs(b-c), abs(a-c), abs(a+b-2*c)
                pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                line[i] = (line[i] + pr) & 255
        out[y*stride:(y+1)*stride] = line; prev = line
    return w, h, ch, bytes(out)

def diff(a, b):
    w1,h1,c1,p1 = load(a); w2,h2,c2,p2 = load(b)
    if (w1,h1,c1) != (w2,h2,c2):
        return {'geometry': f'{w1}x{h1}x{c1} vs {w2}x{h2}x{c2}'}
    stride = w1*c1; changed = 0; total = 0
    x0,y0,x1,y1 = w1, h1, -1, -1; maxd = 0
    for y in range(h1):
        ro = y*stride
        for x in range(w1):
            o = ro + x*c1
            d = max(abs(p1[o+k]-p2[o+k]) for k in range(min(3,c1)))
            if d:
                changed += 1; total += d; maxd = max(maxd, d)
                if x<x0: x0=x
                if x>x1: x1=x
                if y<y0: y0=y
                if y>y1: y1=y
    return {'size': f'{w1}x{h1}', 'changed_px': changed,
            'pct': round(100*changed/(w1*h1), 3), 'max_delta': maxd,
            'mean_delta_over_changed': round(total/changed, 1) if changed else 0,
            'bbox': None if x1 < 0 else f'x{x0}..{x1} y{y0}..{y1} ({x1-x0+1}x{y1-y0+1})'}

if __name__ == '__main__':
    import json
    print(json.dumps(diff(sys.argv[1], sys.argv[2])))
